// One QUIC connection. Send app messages of several classes.
const SHARED = conn.openStream();   // opened once, reused for everything

function send(message) {
  // Multiplex all classes onto one stream to save stream IDs.
  SHARED.write(serialize(message));
}

function sendBulk(bigBlob) {
  // The 50 MB video chunk also goes on SHARED.
  SHARED.write(bigBlob);
}
